import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)

logger = logging.getLogger(__name__)

_BLOCK_SIZE = 8192
# Narrower tile for the strided 1-D select: the affine load already vectorizes
# and a wider tile overflows the on-chip buffer with 64-bit offsets.
_STRIDE1D_BLOCK = 1024
_MAX_RANK = 8


@triton.jit
def _select_copy_contig_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    """Contiguous fast path: copy the selected slice out linearly.

    The wrapper passes ``self.select(dim, index)`` — the selected slice, which
    for a contiguous input with ``dim == 0`` is itself a contiguous tensor
    carrying the correct data pointer (its storage offset is folded in).
    """
    pid = tl.program_id(axis=0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X).
    step = tl.num_programs(axis=0) * BLOCK_SIZE
    block_start = pid * BLOCK_SIZE
    while block_start < n_elements:
        offsets = block_start + tl.arange(0, BLOCK_SIZE)
        mask = offsets < n_elements
        offsets = offsets.to(tl.int64)
        values = tl.load(src_ptr + offsets, mask=mask)
        tl.store(dst_ptr + offsets, values, mask=mask)
        block_start += step


@triton.jit
def _select_copy_strided_kernel(
    src_ptr,
    dst_ptr,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    n_elements,
    src_offset,
    RANK: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    """Gather the selected slice from a (possibly) non-contiguous input.

    The output is contiguous, so its flat offset is the output index. For each
    output index the matching source element is recovered by decomposing it
    along the *slice* shape (row-major, the input dimensions other than
    ``dim``) and applying the input strides for those dimensions, plus the
    precomputed ``src_offset`` (the selected position along ``dim`` and the
    input's storage offset are folded into it).
    """
    pid = tl.program_id(axis=0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X).
    step = tl.num_programs(axis=0) * BLOCK_SIZE
    block_start = pid * BLOCK_SIZE
    src_strides = [s0, s1, s2, s3, s4, s5, s6, s7]
    slice_dims = [d0, d1, d2, d3, d4, d5, d6, d7]
    while block_start < n_elements:
        offsets = block_start + tl.arange(0, BLOCK_SIZE)
        mask = offsets < n_elements
        offsets = offsets.to(tl.int64)

        rem = offsets
        src_offsets = tl.full([], src_offset, tl.int64)
        for j in tl.static_range(RANK - 2, -1, -1):
            idx = rem % slice_dims[j]
            rem = rem // slice_dims[j]
            src_offsets += idx * src_strides[j]

        values = tl.load(src_ptr + src_offsets, mask=mask)
        tl.store(dst_ptr + offsets, values, mask=mask)
        block_start += step


@triton.jit
def _select_copy_stride1d_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    STRIDE: tl.constexpr,
    src_offset,
    BLOCK_SIZE: tl.constexpr,
):
    """Strided 1-D select: ``out[i] = src[src_offset + i * STRIDE]``.

    The address is affine in the flat index, so the backend can emit a strided
    DMA instead of the per-element index decomposition (which is much slower).
    """
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0) * BLOCK_SIZE
    lanes = tl.arange(0, BLOCK_SIZE)
    base = pid * BLOCK_SIZE
    while base < n_elements:
        offs = base + lanes
        mask = offs < n_elements
        values = tl.load(src_ptr + src_offset + offs * STRIDE, mask=mask)
        tl.store(dst_ptr + offs, values, mask=mask)
        base += step


@triton.jit
def _select_copy_rows_kernel(
    src_ptr,
    dst_ptr,
    n_rows,
    src_offset,
    SLICE_DIMS: tl.constexpr,
    SLICE_STRIDES: tl.constexpr,
    ROW_LEN: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    """Row-wise copy for a strided slice whose innermost axis is contiguous.

    Only the row index is decomposed (scalar arithmetic); each row is a plain
    vectorized copy, instead of the per-element index math of the general
    gather kernel.
    """
    NDIM: tl.constexpr = len(SLICE_DIMS)
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0)
    lanes = tl.arange(0, BLOCK_SIZE)
    mask = lanes < ROW_LEN
    row = pid
    while row < n_rows:
        rem = row
        off = src_offset
        for j in tl.static_range(NDIM - 2, 0, -1):
            c = rem % SLICE_DIMS[j]
            rem = rem // SLICE_DIMS[j]
            off += c * SLICE_STRIDES[j]
        off += rem * SLICE_STRIDES[0]
        values = tl.load(src_ptr + off + lanes, mask=mask)
        tl.store(dst_ptr + row * ROW_LEN + lanes, values, mask=mask)
        row += step


def select_copy(self: torch.Tensor, dim: int, index: int):
    """Return a copy of ``self`` with the selected slice along ``dim`` removed.

    This mirrors ``aten::select_copy``: it is the out-of-place counterpart of
    ``torch.select`` (equivalent to ``self.select(dim, index).clone()``). The
    result is one rank lower than the input, contiguous, and never a view or
    alias of ``self``. Negative ``dim``/``index`` are normalized exactly like
    PyTorch; 0-dim inputs, empty slices and out-of-range indices are rejected
    with the same error messages PyTorch raises.
    """
    logger.debug("GEMS SELECT_COPY")

    if self.dim() == 0:
        raise RuntimeError("select() cannot be applied to a 0-dim tensor.")

    dim_size = self.size(dim)
    if index < -dim_size or index >= dim_size:
        raise RuntimeError(
            f"select(): index {index} out of range for tensor of size "
            f"[{', '.join(str(s) for s in self.shape)}] at dimension {dim}"
        )
    dim = dim % self.dim()
    index = index % dim_size

    shape = list(self.shape)
    del shape[dim]
    out = torch.empty(shape, dtype=self.dtype, device=self.device)

    n_elements = out.numel()
    if n_elements == 0:
        return out

    # Triton receives ``self``'s data pointer, which already includes the
    # storage offset, so only the selected step along ``dim`` is added here.
    src_offset = index * int(self.stride(dim))

    if self.is_contiguous() and (dim == 0 or n_elements <= 1):
        # For a contiguous input the selected slice is itself contiguous only
        # when ``dim == 0`` (the remaining strides are ``(..., 1)``); for any
        # other ``dim`` the slice keeps stride != 1, so use the strided gather.
        with torch_device_fn.device(self.device):
            grid = lambda meta: (
                min(triton.cdiv(n_elements, meta["BLOCK_SIZE"]), _MAX_GRID_X),
            )
            _select_copy_contig_kernel.run(
                self.select(dim, index),
                out,
                n_elements,
                BLOCK_SIZE=_BLOCK_SIZE,
                grid=grid,
                warmup=False,
            )
        return out

    if self.dim() == 2 and n_elements > 0:
        # Any 2-D select yields a 1-D result whose addresses are affine in the
        # flat index (``out[i] = src[base + i * other_stride]``), so the backend
        # can emit one strided DMA instead of a per-element gather.
        with torch_device_fn.device(self.device):
            _select_copy_stride1d_kernel.run(
                self,
                out,
                n_elements,
                STRIDE=int(self.stride(1 - dim % 2)),
                src_offset=src_offset,
                BLOCK_SIZE=_STRIDE1D_BLOCK,
                grid=(min(triton.cdiv(n_elements, _STRIDE1D_BLOCK), _MAX_GRID_X),),
                warmup=False,
            )
        return out

    rank = self.dim()
    if rank > _MAX_RANK:
        raise RuntimeError(
            f"select_copy supports at most {_MAX_RANK} dimensions, got {rank}"
        )
    # Both arrays describe the *slice* (the input dimensions other than
    # ``dim``), padded to 8 entries with size-1 / zero-stride slots so the
    # kernel always receives its full fixed argument sets.
    raw_strides = [int(s) for s in self.stride()]
    raw_dims = list(self.shape)
    del raw_strides[dim]
    del raw_dims[dim]
    if raw_dims and raw_strides[-1] == 1 and n_elements > 0:
        # Innermost axis is contiguous: copy row by row (scalar row index,
        # vectorized row body) instead of decomposing every element.
        row_len = raw_dims[-1]
        n_rows = n_elements // row_len
        row_block = min(_BLOCK_SIZE, max(1, triton.next_power_of_2(row_len)))
        with torch_device_fn.device(self.device):
            _select_copy_rows_kernel.run(
                self,
                out,
                n_rows,
                src_offset,
                SLICE_DIMS=tuple(raw_dims),
                SLICE_STRIDES=tuple(raw_strides),
                ROW_LEN=row_len,
                BLOCK_SIZE=row_block,
                grid=(min(n_rows, _MAX_GRID_X),),
                warmup=False,
            )
        return out
    src_strides = raw_strides
    slice_dims = raw_dims
    src_strides = src_strides + [0] * (_MAX_RANK - len(src_strides))
    slice_dims = slice_dims + [1] * (_MAX_RANK - len(slice_dims))

    with torch_device_fn.device(self.device):
        grid = lambda meta: (
            min(triton.cdiv(n_elements, meta["BLOCK_SIZE"]), _MAX_GRID_X),
        )
        _select_copy_strided_kernel.run(
            self,
            out,
            *src_strides,
            *slice_dims,
            n_elements,
            src_offset,
            RANK=rank,
            BLOCK_SIZE=_BLOCK_SIZE,
            grid=grid,
            warmup=False,
        )
    return out
